import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from sqlalchemy import select, text
from sqlalchemy.dialects import postgresql

from app.data.database import Database
from app.data.seed import seed
from app.domain.models import Base

db = Database("sqlite://")
db.create_tables()
seed(db, "pbkdf2:sha256:1000", demo_orders=True)
out = [
    "-- SaigonBite OFDH sample data (PostgreSQL). Generated by scripts/export_data.py. Do not edit by hand.",
    "-- All demo accounts use the password 'password' (development only).\n",
]
with db.engine.connect() as conn:
    for table in Base.metadata.sorted_tables:
        rows = conn.execute(
            select(table).order_by(*table.primary_key.columns)
        ).fetchall()
        if not rows:
            continue
        out.append(f"-- {table.name}")
        for row in rows:
            values = dict(row._mapping)
            stmt = table.insert().values(**values)
            out.append(
                str(
                    stmt.compile(
                        dialect=postgresql.dialect(),
                        compile_kwargs={"literal_binds": True},
                    )
                )
                + ";"
            )
        if "id" in table.c and len(table.primary_key.columns) == 1:
            out.append(
                f"SELECT setval(pg_get_serial_sequence('{table.name}', 'id'), (SELECT max(id) FROM {table.name}));"
            )
        out.append("")
target = Path(__file__).resolve().parent.parent / "sql" / "data.sql"
target.write_text("\n".join(out), encoding="utf-8")
print("wrote", target, len(out), "lines")
